import { test, expect } from '@playwright/test';

test.describe('Animated Transitions Between Async Page Loads', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display animated transition when navigating between async page loads', async ({ page }) => {
    // Verify initial page is loaded
    const welcomeMessage = page.getByRole('heading', { name: /welcome/i });
    await expect(welcomeMessage).toBeVisible();

    // Click button to trigger async page load
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for transition animation to complete
    await page.waitForTimeout(500);

    // Verify loading spinner is visible during transition
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for data to load
    await page.waitForTimeout(1000);

    // Verify loading spinner is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify new content is displayed
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();

    // Verify data rows are present
    const dataRows = page.getByRole('row');
    await expect(dataRows).toHaveCount(5);

    // Verify animated transition class is applied
    const contentContainer = page.locator('[data-testid="content-container"]');
    await expect(contentContainer).toHaveClass(/transition-active/);
  });

  test('should handle multiple async page loads with animated transitions', async ({ page }) => {
    // First async page load
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for first transition
    await page.waitForTimeout(500);

    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for data to load
    await page.waitForTimeout(1000);

    // Verify data table is visible
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();

    // Second async page load
    await loadButton.click();

    // Wait for second transition
    await page.waitForTimeout(500);

    // Verify loading spinner is visible again
    await expect(loadingSpinner).toBeVisible();

    // Wait for data to load
    await page.waitForTimeout(1000);

    // Verify data table is still visible and updated
    await expect(dataTable).toBeVisible();
    const dataRows = page.getByRole('row');
    await expect(dataRows).toHaveCount(5);

    // Verify transition animation class is applied on second load
    const contentContainer = page.locator('[data-testid="content-container"]');
    await expect(contentContainer).toHaveClass(/transition-active/);
  });
});
